// Package grpc contains the inbound ConnectRPC adapter for the sensor-service.
// NOTE: proto types are generated by buf generate.
package grpc

import (
	"context"

	"connectrpc.com/connect"
	"p9e.in/samavaya/packages/errors"
	"p9e.in/samavaya/packages/p9context"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate
	pb "p9e.in/samavaya/agriculture/sensor-service/api/v1"
	"p9e.in/samavaya/agriculture/sensor-service/api/v1/sensorv1connect"
	"p9e.in/samavaya/agriculture/sensor-service/internal/domain"
	"p9e.in/samavaya/agriculture/sensor-service/internal/ports/inbound"
)

// SensorHandler is the ConnectRPC inbound adapter.
type SensorHandler struct {
	sensorv1connect.UnimplementedSensorServiceHandler
	svc inbound.SensorService
	log *p9log.Helper
}

// NewSensorHandler creates a new ConnectRPC sensor handler.
func NewSensorHandler(svc inbound.SensorService, log p9log.Logger) *SensorHandler {
	return &SensorHandler{
		svc: svc,
		log: p9log.NewHelper(p9log.With(log, "component", "SensorHandler")),
	}
}

// RegisterSensor handles sensor registration requests.
func (h *SensorHandler) RegisterSensor(ctx context.Context, req *connect.Request[pb.RegisterSensorRequest]) (*connect.Response[pb.RegisterSensorResponse], error) {
	h.log.Infow("msg", "RegisterSensor request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetDeviceId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "device_id is required")
	}
	entity := &domain.Sensor{Name: req.Msg.GetDeviceId()}
	created, err := h.svc.CreateSensor(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.RegisterSensorResponse{Sensor: sensorToProto(created)}), nil
}

// GetSensor handles get requests.
func (h *SensorHandler) GetSensor(ctx context.Context, req *connect.Request[pb.GetSensorRequest]) (*connect.Response[pb.GetSensorResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity, err := h.svc.GetSensor(ctx, req.Msg.GetId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetSensorResponse{Sensor: sensorToProto(entity)}), nil
}

// ListSensors handles list requests.
func (h *SensorHandler) ListSensors(ctx context.Context, req *connect.Request[pb.ListSensorsRequest]) (*connect.Response[pb.ListSensorsResponse], error) {
	params := domain.ListSensorParams{PageSize: req.Msg.GetPageSize()}
	entities, total, err := h.svc.ListSensors(ctx, params)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	protos := make([]*pb.Sensor, 0, len(entities))
	for i := range entities {
		protos = append(protos, sensorToProto(&entities[i]))
	}
	return connect.NewResponse(&pb.ListSensorsResponse{Sensors: protos, TotalCount: total}), nil
}

// UpdateSensor handles update requests.
func (h *SensorHandler) UpdateSensor(ctx context.Context, req *connect.Request[pb.UpdateSensorRequest]) (*connect.Response[pb.UpdateSensorResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity := &domain.Sensor{}
	entity.UUID = req.Msg.GetId()
	updated, err := h.svc.UpdateSensor(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.UpdateSensorResponse{Sensor: sensorToProto(updated)}), nil
}

// DecommissionSensor handles sensor decommission requests.
func (h *SensorHandler) DecommissionSensor(ctx context.Context, req *connect.Request[pb.DecommissionSensorRequest]) (*connect.Response[pb.DecommissionSensorResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	if err := h.svc.DeleteSensor(ctx, req.Msg.GetId()); err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.DecommissionSensorResponse{Sensor: sensorToProto(nil)}), nil
}

func sensorToProto(e *domain.Sensor) *pb.Sensor {
	if e == nil {
		return nil
	}
	return &pb.Sensor{
		Id:       e.UUID,
		TenantId: e.TenantID,
		Status:   pb.SensorStatus(pb.SensorStatus_value["SENSOR_STATUS_"+string(e.Status)]),
	}
}
